rawInput.command:
function Get-Frontmatter([string]$path) {
  $lines = [System.IO.File]::ReadAllLines($path)
  if ($lines.Length -eq 0 -or $lines[0] -ne '---') { return $null }
  $end = -1
  for ($i = 1; $i -lt $lines.Length; $i++) {
    if ($lines[$i] -eq '---') { $end = $i; break }
  }
  if ($end -lt 0) { return $null }
  return ($lines[1..($end-1)] -join "`n")
}

$docs = "C:\Users\magicvr\Documents\Code\goal-governance\docs"
Write-Output "===== ALL WORKSPACE FRONTMATTER (identity fields) ====="
Get-ChildItem -LiteralPath (Join-Path $docs "workspaces") -Directory | ForEach-Object {
  $wm = Join-Path $_.FullName "workspace.md"
  Write-Output "DIR=$($_.Name)"
  $fm = Get-Frontmatter $wm
  if ($null -eq $fm) { Write-Output "NO_FRONTMATTER"; return }
  $fm -split "`n" | Where-Object { $_ -match '^(id|root_goal|canonical_scope|shared_materials_catalog|status|vision_role|plan_refs|primary_plan|title):' } | ForEach-Object { Write-Output $_ }
  Write-Output "----"
}

$ws = Join-Path $docs "workspaces\workspace-002-methodology-skills-feedback"
Write-Output "===== WS002 GOAL DIRS MATCHING 018 ====="
Get-ChildItem -LiteralPath $ws -Directory | Where-Object { $_.Name -match '^GOAL-0*18-' -or $_.Name -match '^GOAL-018' } | ForEach-Object { $_.Name }
Write-Output "===== ALL GOAL DIRS IN WS002 (names only) ====="
Get-ChildItem -LiteralPath $ws -Directory | Where-Object { $_.Name -like "GOAL-*" } | ForEach-Object { $_.Name }

