rawInput.command:
function Get-Frontmatter([string]$path) {
  $lines = [System.IO.File]::ReadAllLines($path)
  if ($lines.Length -eq 0 -or $lines[0] -ne '---') { return $null }
  $end = -1
  for ($i = 1; $i -lt $lines.Length; $i++) {
    if ($lines[$i] -eq '---') { $end = $i; break }
  }
  if ($end -lt 0) { return $null }
  return ($lines[1..($end-1)] -join "`n")
}

$enc = New-Object System.Text.UTF8Encoding $false
function Show-Fields([string]$label, [string]$path, [string[]]$keys) {
  Write-Output "===== $label ====="
  Write-Output "PATH=$path"
  $item = Get-Item -LiteralPath $path
  $link = [bool]($item.Attributes -band [IO.FileAttributes]::ReparsePoint)
  Write-Output "LINK=$link"
  $text = [System.IO.File]::ReadAllText($path, $enc)
  $lines = $text -split "`r?`n"
  if ($lines[0] -ne '---') { Write-Output "NO_FM"; return }
  $end = 0
  for ($i = 1; $i -lt $lines.Length; $i++) { if ($lines[$i] -eq '---') { $end = $i; break } }
  $fm = $lines[1..($end-1)]
  foreach ($line in $fm) {
    foreach ($k in $keys) {
      if ($line -match "^${k}:") { Write-Output $line }
    }
  }
}

