Show-Fields "ROOT META" "$base\docs\workspaces\workspace-002-methodology-skills-feedback\GOAL-001-methodology-skills-feedback-evolution\00-meta.md" @("id","title","status","parent","plan_refs","primary_plan","progress")
Show-Fields "GOAL018 META" "$base\docs\workspaces\workspace-002-methodology-skills-feedback\GOAL-018-host-wait-and-audit-config\00-meta.md" @("id","title","status","parent","progress","created","updated","version")
Show-Fields "VP-002" "$base\docs\vision\plans\VP-002-methodology-skills-feedback-evolution.md" @("id","title","status","vision_ref","vision_id","lead_workspace","doc_type")
Show-Fields "CHARTER" "$base\docs\vision\charter.md" @("doc_type","vision_id","version","status","title")

Write-Output "===== GOAL-TREE IDENTITY ROWS ====="
$tree = "$base\docs\workspaces\workspace-002-methodology-skills-feedback\goal-tree.md"
$tlines = [System.IO.File]::ReadAllLines($tree)
